def ThreeLayerTrace.finalPhase (trace : ThreeLayerTrace) : Option ThreeLayerPhase :=
  trace.handoffs.foldlM ThreeLayerTrace.advance trace.start

/-- Every handoff in a trace is locally valid. -/

def ThreeLayerTrace.allValid (trace : ThreeLayerTrace) : Prop :=
  ∀ handoff ∈ trace.handoffs, handoff.valid

/-- Canonical upper-to-reviewer trace used as the finite teaching witness. -/

def accessEquiv (n : Nat) (loader : Equiv.Perm (Word n)) :
    Equiv.Perm (Word n × Word n) :=
  (liftLoaderEquiv n loader).trans (modularSumEquiv n)

def paperSingleQubitUpperBound (n l : Nat) : Nat :=
  (2 ^ l + 1) * (32 * n - 48)

/-- Source-facing CNOT upper bound printed in the same lemma. -/

def paperCnotUpperBound (n l : Nat) : Nat :=
  25 * 2 ^ l * n - 36 * 2 ^ l + 32 * n - 48

/-- Source-facing clean-ancilla upper bound printed in the same lemma. -/

def primitiveAccess3ReversibleProgram : ReversibleProgram 7 :=
  [.x 0, .x 1] ++ modularAdd3ReversibleProgram

/-- Full-space reversible semantics of the fixed primitive witness. -/

def primitiveAccess3BasisEquiv : PrimitiveBasis 7 ≃ PrimitiveBasis 7 :=
  evalReversibleProgram primitiveAccess3ReversibleProgram

/-- Exact clean-workspace action of the expanded access circuit. -/

def fromSpec (spec : BlockEncodingSpec α rows cols) : BlockEncodingCost :=
  fromLayoutAndResource spec.layout spec.resource

/-- Strict lexicographic improvement used by candidate-population selection. -/

def cost (candidate : OperatorBlockEncodingCandidate α systemQubits) :
    BlockEncodingCost :=
  {
    auxiliaryQubits := candidate.auxiliaryQubits
    gateCount := candidate.resource.gates
    depth := candidate.resource.depth
    oracleCalls := candidate.resource.oracleCalls
  }

theorem unitary {α : Type u} {rows cols : Nat}
    (v : VerifiedBlockEncoding α rows cols) : v.isUnitary :=
  v.unitaryProof

theorem correct {α : Type u} {rows cols : Nat}
    (v : VerifiedBlockEncoding α rows cols) : v.blockCorrect :=
  v.blockProof

theorem resource_ok {α : Type u} {rows cols : Nat}
    (v : VerifiedBlockEncoding α rows cols) : v.resourceBound :=
  v.resourceProof

def permMatrix {n : Nat} (p : Fin n -> Fin n) : Matrix n n Rat :=
  fun row col => if row = p col then 1 else 0

/-- Column inner products for rational matrix-level orthogonality checks. -/

def columnInner {n : Nat} (U : Matrix n n Rat) (i j : Fin n) : Rat :=
  (List.finRange n).foldl (fun acc k => acc + U k i * U k j) 0

/-- Row inner products for rational matrix-level orthogonality checks. -/

def oneSparseMatrix {n : Nat} (c : Fin n -> Fin n) (amp : Fin n -> Rat) :
    Matrix n n Rat :=
  fun row col => amp col * kroneckerRat row (c col)

def IsSymmetric {n : Nat} (A : Matrix n n Rat) : Prop :=
  forall i j : Fin n, A i j = A j i

/-- A symmetric full matrix has a symmetric clean block under any embedding. -/

def scalarDilationRowDot (x y : Rat) (rowA rowB : Fin 2) : Rat :=
  scalarDilation x y rowA fin2Zero * scalarDilation x y rowB fin2Zero +
    scalarDilation x y rowA fin2One * scalarDilation x y rowB fin2One

def clean {system total : Nat} (cert : ExactCleanBlock system total) :
    Matrix system system Rat :=
  cleanBlockBy cert.embed cert.U

def matrixScale (c : Rat) (A : Matrix rows cols Rat) : Matrix rows cols Rat :=
  fun row col => c * A row col

/-- Pointwise addition for the project-local matrix backend. -/

def matrixAdd (A B : Matrix rows cols Rat) : Matrix rows cols Rat :=
  fun row col => A row col + B row col

/-- Two-term weighted sum, the finite clean-block algebra behind a 2-term LCU. -/

def weightedSum2 (leftWeight rightWeight : Rat)
    (left right : Matrix rows cols Rat) : Matrix rows cols Rat :=
  fun row col => leftWeight * left row col + rightWeight * right row col

def signalSystemBlockRowIndex (rows : Nat) (signalIdx systemIdx : Nat) : Nat :=
  signalIdx * rows + systemIdx

/-- Compound column index for a signal value and a system-column index. -/

def extendPrefix {N r : ℕ} (hr : r ≤ N) (e : Fin r ↪ Fin N) :
    (k : ℕ) → k ≤ r → Equiv.Perm (Fin N)
  | 0, _ => Equiv.refl _
  | k + 1, hk =>
      let p := extendPrefix hr e k (by omega)
      p.trans (Equiv.swap (p ⟨k, by omega⟩) (e ⟨k, by omega⟩))

def permuteColumns {N : ℕ} (U : _root_.Matrix (Fin N) (Fin N) ℝ)
    (p : Equiv.Perm (Fin N)) : _root_.Matrix (Fin N) (Fin N) ℝ :=
  U.submatrix id p.symm

def zero (rows cols : Nat) (α : Type u) [OfNat α 0] : Matrix rows cols α :=
