def derivativeOracleResource (n : Nat) (s : Stencil) : Resource :=
  bandedSparseAccessResource n s.leftRadius

/-- The derivative oracle's pure ancilla count is n - 1 (from Lemma 1). -/

def oneTermRobinGlobalSparseAddress (n s i : Nat) : Nat :=
  (oneTermRobinGlobalSparseOffset n s + i) % gridSize n

/-- The global sparse-slot address is always an `n`-bit row address. -/

def robinSparseReverseColumnIndex (n target row : Nat) : Nat :=
  let N := gridSize n
  if row = 0 then target
  else if row = 1 then target
  else if 2 ≤ row ∧ row ≤ N - 3 then target + 2 - row
  else if row = N - 2 then target - (N - 4)
  else if row = N - 1 then target - (N - 3)
  else target

/-- Normal form for the leftmost row of the executable Robin sparse map. -/

def bandedSparseAccessPaperAddressInRange (p : OneTermRobinParameters) (j : Nat) : Bool :=
  decide (bandedSparseAccessPaperAddress p j < (1 <<< p.n))

/-- Boolean form of the executable `O_D^BS` address-range check. -/

def sparseAmplitudeOracleDTCosHalf (row sparse : Nat) : Coeff :=
  Coeff.symbol s!"odts_cos_half_{row}_{sparse}"

/-- Symbolic sine half-angle entry for the Lemma 3 O_DT^S rotation. -/

def boundaryRotationCosHalf (row sparse : Nat) : Coeff :=
  Coeff.symbol s!"boundary_cos_half_{row}_{sparse}"

/-- Symbolic sine half-angle entry for the `Ry_boundary` rotation. -/

def add (A B : CMatrix ι κ) : CMatrix ι κ :=
  fun i j => A i j + B i j

/-- Entrywise subtraction. -/

def sub (A B : CMatrix ι κ) : CMatrix ι κ :=
  fun i j => A i j - B i j

/-- Scalar multiplication. -/

def scale (c : ℂ) (A : CMatrix ι κ) : CMatrix ι κ :=
  fun i j => c * A i j

/-- The matrix adjoint written directly as conjugate transpose. -/

def adjoint (A : CMatrix ι ι) : CMatrix ι ι :=
  fun i j => conj (A j i)

/-- Source-level Hermitian predicate. -/

def IsHermitian (A : CMatrix ι ι) : Prop :=
  ∀ i j, A i j = conj (A j i)

/-- The Hermitian part `(A + A†)/2`. -/

def hermitianPart (A : CMatrix ι ι) : CMatrix ι ι :=
  fun i j => (A i j + conj (A j i)) / 2

/-- The second Hermitian piece `(A - A†)/(2i)`. -/

def antiHermitianPart (A : CMatrix ι ι) : CMatrix ι ι :=
  fun i j => (A i j - conj (A j i)) / (2 * Complex.I)

/-- The two canonical pieces reconstruct the original matrix. -/

def S1 (A B : CMatrix ι ι) : CMatrix (Sum ι ι) (Sum ι ι) :=
  hermitianPart (homogenizedS A B)

/-- `S₂ = (S - S†)/(2i)`. -/

def S2 (A B : CMatrix ι ι) : CMatrix (Sum ι ι) (Sum ι ι) :=
  antiHermitianPart (homogenizedS A B)

/-- The homogenized matrix is exactly `S₁ + i S₂`. -/

def A (cert : OneDimCompositionCertificate η ι ξ) : CMatrix ι ι :=
  sumTerms cert.terms

/-- `A†`, exposed as a named stage because Theorem 4 combines both `A` and `A†`. -/

def Adagger (cert : OneDimCompositionCertificate η ι ξ) : CMatrix ι ι :=
  adjoint cert.A

/-- The adjoint assembled from the one-term adjoints equals the adjoint of `A`. -/

def first (cert : OneDimCompositionCertificate η ι ξ) :=
  S1 cert.A cert.B

/-- Second Hermitian source block. -/

def second (cert : OneDimCompositionCertificate η ι ξ) :=
  S2 cert.A cert.B

/-- Final Schrödingerised Hamiltonian. -/

def H (cert : OneDimCompositionCertificate η ι ξ) :=
  oneDimHamiltonian cert.A cert.B cert.xXi

/-- The certificate reconstructs `S` from the two Hermitian pieces. -/

def headBit (index : ℕ) : Fin 2 :=
  if (index / 2) % 2 = 0 then ⟨index % 2, by omega⟩
  else flipBit ⟨index % 2, by omega⟩

noncomputable def compileSOGray {q : ℕ}
    (A : _root_.Matrix (Fin (2 ^ (q + 1))) (Fin (2 ^ (q + 1))) ℝ) : PrimitiveCircuit (q + 1) :=
  compileSteps (decomposeSO A)

noncomputable def compileSO {q : ℕ}
    (A : _root_.Matrix (PrimitiveBasis (q + 1)) (PrimitiveBasis (q + 1)) ℝ) :
    PrimitiveCircuit (q + 1) := compileSOGray (grayCoordinates A)

def leftCoefficient (k r : ℕ) : ℝ :=
  ∑ i ∈ Finset.range (k + 1), ∑ j ∈ Finset.range (k - i + 1),
    if r = i + j then sourceCoefficient k i * elevationWeight k i j else 0

def restrictCoefficients (d : ℕ) (u v : ℝ) (c : ℕ → ℝ) : ℕ → ℝ :=
  leftRestriction ((v - u) / (1 - u)) (rightRestriction d u c)

/-- Exact affine restriction; no floating-point quantities occur. -/

def halfSubdivision (d : ℕ) (bit : Bool) (c : ℕ → ℝ) : ℕ → ℝ :=
  if bit then rightRestriction d (1 / 2) c else leftRestriction (1 / 2) c

/-- The local coordinate of one binary child. -/

def Full (lower upper first size : ℕ) : Prop :=
  lower ≤ first ∧ first + size ≤ upper

/-- A dyadic node is disjoint from the half-open target interval. -/

def leftKernel (n : ℕ) (L : ℝ) : Kernel ScalarBond :=
  scalarCore 0 (cutIndex n L) (boundarySchedule (cutIndex n L))
    (leftInject (-Real.pi * L) (gridStep n L)) (leftFree (gridStep n L))

def middleKernel (k n : ℕ) (L : ℝ) : Kernel (InjectionBond k) :=
  injectionCore k (-Real.pi * L) (gridStep n L) (cutIndex n L) (2 ^ n)
    (boundarySchedule (cutIndex n L))

def exponentialMassClosed (start step : ℝ) (count : ℕ) : ℝ :=
  if step = 0 then (count : ℝ) * Real.exp (2 * start)
  else Real.exp (2 * start) *
    ((Real.exp (2 * step)) ^ count - 1) / (Real.exp (2 * step) - 1)

/-- Exact geometric mass of squared exponential amplitudes. -/

def jetPolynomial (a : ℝ) (k : ℕ) (v : ℕ → ℝ) : ℝ[X] :=
  taylor (-a) (∑ j ∈ Finset.range (k + 1), monomial j (v j / (j.factorial : ℝ)))

/-- Convert Taylor coefficients to ordinary iterated derivatives. -/

def coefficientSeries (k : ℕ) : PowerSeries ℝ :=
  PowerSeries.exp ℝ * (PowerSeries.invOneSubPow ℝ (k + 1)).val

/-- The exact polynomial `A_k`, implemented as a finite Taylor truncation. -/

def coefficientPolynomial (k : ℕ) : ℝ[X] :=
  PowerSeries.trunc (k + 1) (coefficientSeries k)

/-- One endpoint cardinal factor in the symmetric closed-form Hermite formula. -/

def sourceInterpolant (k : ℕ) : ℝ[X] :=
  taylor 1 (C (Real.exp (-1)) * endpointFactor k +
    (endpointFactor k).comp (1 - X))

def smoothInitial (k : ℕ) (p : ℝ) : ℝ :=
  if p < -1 then Real.exp p else
    if p ≤ 0 then (sourceInterpolant k).eval p else Real.exp (-p)

def gridPoint (n : ℕ) (L : ℝ) (j : Fin (gridSize n)) : ℝ :=
  -Real.pi * L + (j.val : ℝ) * (2 * Real.pi * L / (gridSize n : ℝ))

/-- The physical sample, without changing the polynomial on the splice interval. -/

def normalizedAmplitude (k n : ℕ) (L : ℝ) (j : Fin (gridSize n)) : ℂ :=
  ((sampledAmplitude k n L j / sampleNorm k n L : ℝ) : ℂ)

/-- An actual list of primitive instructions on precisely `n` wires. -/

def hermiteCircuit (k n : ℕ) (L : ℝ) : PrimitiveCircuit n :=
  prepareCircuit n (fun b => sampledAmplitude k n L (primitiveBasisLEEquiv n b))

/-- The exact primitive denotation, reindexed by little-endian integers. -/

def hermiteUnitary (k n : ℕ) (L : ℝ) :
    _root_.Matrix (Fin (gridSize n)) (Fin (gridSize n)) ℂ :=
  prepareMatrixLE (sampledAmplitude k n L)

def hermiteCertificate (k n : ℕ) (L : ℝ) : ComplexStatePreparationCertificate n where
  target := {
    amplitudes := normalizedAmplitude k n L
    normalization := (∑ j, Complex.normSq (normalizedAmplitude k n L j)) = 1
    source := "Exact exponential–Hermite–exponential initial datum on a little-endian grid"
  }
  gate := {
    matrix := hermiteUnitary k n L
    unitary := hermiteUnitary_unitary k n L
  }
  normalizationProof := hermite_normalized k n L
  preparationProof := hermite_stateAction k n L

def transfer (d : ℕ) : List ℝ → (Fin (d + 1) → ℝ) → (Fin (d + 1) → ℝ)
  | [], v => v
  | w :: ws, v => transfer d ws (v ᵥ* translationCore d w)

