def joinIndex {q : Nat} (bit : Fin 2) (rest : Fin (2 ^ q)) : Run (Fin (2 ^ (q + 1))) :=
  let offset := charge .field (bit.val * 2 ^ q)
  let joined := charge .field (offset.value + rest.val)
  ⟨⟨joined.value, by
    have hb := bit.isLt
    have hr := rest.isLt
    dsimp [joined, offset, charge]
    simp only [pow_succ]
    nlinarith⟩, offset.cost + joined.cost⟩

